430  /*
   431   * Serialize
   432   */
   433
   434  struct hb_serialize_context_t
   435  {
   436    inline hb_serialize_context_t (void *start_, unsigned int size)
   437    {
   438      this->start = (char *) start_;
   439      this->end = this->start + size;
   440
   441      this->ran_out_of_room = false;
   442      this->head = this->start;
   443      this->debug_depth = 0;
   444    }
   445
   446    template <typename Type>
   447    inline Type *start_serialize (void)
   448    {
   449      DEBUG_MSG_LEVEL (SERIALIZE, this->start, 0, +1,
   450                       "start [%p..%p] (%lu bytes)",
   451                       this->start, this->end,
   452                       (unsigned long) (this->end - this->start));
   453
   454      return start_embed<Type> ();
   455    }
   456
   457    inline void end_serialize (void)
   458    {
   459      DEBUG_MSG_LEVEL (SERIALIZE, this->start, 0, -1,
   460                       "end [%p..%p] serialized %d bytes; %s",
   461                       this->start, this->end,
   462                       (int) (this->head - this->start),
   463                       this->ran_out_of_room ? "RAN OUT OF ROOM" : "did not ran out of room");
   464    }
   465
   466    template <typename Type>
   467    inline Type *copy (void) const
   468    {
   469      assert (!this->ran_out_of_room);
   470      unsigned int len = this->head - this->start;
   471      void *p = malloc (len);
   472      if (p)
   473        memcpy (p, this->start, len);
   474      return reinterpret_cast<Type *> (p);
   475    }
   476    inline hb_bytes_t copy_bytes (void) const
   477    {
   478      assert (!this->ran_out_of_room);
   479      unsigned int len = this->head - this->start;
   480      void *p = malloc (len);
   481      if (p)
   482        memcpy (p, this->start, len);
   483      else
   484        return hb_bytes_t ();
   485      return hb_bytes_t (p, len);
   486    }
   487    inline hb_blob_t *copy_blob (void) const
   488    {
   489      assert (!this->ran_out_of_room);
   490      return hb_blob_create (this->start,
   491                             this->head - this->start,
   492                             HB_MEMORY_MODE_DUPLICATE,
   493                             nullptr, nullptr);
   494    }
   495
   496    template <typename Type>
   497    inline Type *allocate_size (unsigned int size)
   498    {
   499      if (unlikely (this->ran_out_of_room || this->end - this->head < ptrdiff_t (size))) {
   500        this->ran_out_of_room = true;
   501        return nullptr;
   502      }
   503      memset (this->head, 0, size);
   504      char *ret = this->head;
   505      this->head += size;
   506      return reinterpret_cast<Type *> (ret);
   507    }
   508
   509    template <typename Type>
   510    inline Type *allocate_min (void)
   511    {
   512      return this->allocate_size<Type> (Type::min_size);
   513    }
   514
   515    template <typename Type>
   516    inline Type *start_embed (void)
   517    {
   518      Type *ret = reinterpret_cast<Type *> (this->head);
   519      return ret;
   520    }
   521
   522    template <typename Type>
   523    inline Type *embed (const Type &obj)
   524    {
   525      unsigned int size = obj.get_size ();
   526      Type *ret = this->allocate_size<Type> (size);
   527      if (unlikely (!ret)) return nullptr;
   528      memcpy (ret, obj, size);
   529      return ret;
   530    }
   531
   532    template <typename Type>
   533    inline Type *extend_min (Type &obj)
   534    {
   535      unsigned int size = obj.min_size;
   536      assert (this->start <= (char *) &obj && (char *) &obj <= this->head && (char *) &obj + size >= this->head);
   537      if (unlikely (!this->allocate_size<Type> (((char *) &obj) + size - this->head))) return nullptr;
   538      return reinterpret_cast<Type *> (&obj);
   539    }
   540
