    99  static bool
   100  _subset_table (hb_subset_plan_t *plan,
   101                 hb_tag_t          tag)
   102  {
   103    DEBUG_MSG(SUBSET, nullptr, "begin subset %c%c%c%c", HB_UNTAG(tag));
   104    bool result = true;
   105    switch (tag) {
   106      case HB_OT_TAG_glyf:
   107        result = _subset<const OT::glyf> (plan);
   108        break;
   109      case HB_OT_TAG_hdmx:
   110        result = _subset<const OT::hdmx> (plan);
   111        break;
   112      case HB_OT_TAG_head:
   113        // TODO that won't work well if there is no glyf
   114        DEBUG_MSG(SUBSET, nullptr, "skip head, handled by glyf");
   115        result = true;
   116        break;
   117      case HB_OT_TAG_hhea:
   118        DEBUG_MSG(SUBSET, nullptr, "skip hhea handled by hmtx");
   119        return true;
   120      case HB_OT_TAG_hmtx:
   121        result = _subset<const OT::hmtx> (plan);
   122        break;
   123      case HB_OT_TAG_vhea:
   124        DEBUG_MSG(SUBSET, nullptr, "skip vhea handled by vmtx");
   125        return true;
   126      case HB_OT_TAG_vmtx:
   127        result = _subset<const OT::vmtx> (plan);
   128        break;
   129      case HB_OT_TAG_maxp:
   130        result = _subset<const OT::maxp> (plan);
   131        break;
   132      case HB_OT_TAG_loca:
   133        DEBUG_MSG(SUBSET, nullptr, "skip loca handled by glyf");
   134        return true;
   135      case HB_OT_TAG_cmap:
   136        result = _subset<const OT::cmap> (plan);
   137        break;
   138      case HB_OT_TAG_os2:
   139        result = _subset<const OT::os2> (plan);
   140        break;
   141      case HB_OT_TAG_post:
   142        result = _subset<const OT::post> (plan);
   143        break;
   144      default:
   145        hb_blob_t *source_table = hb_face_reference_table(plan->source, tag);
   146        if (likely (source_table))
   147          result = plan->add_table(tag, source_table);
   148        else
   149          result = false;
   150        hb_blob_destroy (source_table);
   151        break;
   152    }
   153    DEBUG_MSG(SUBSET, nullptr, "subset %c%c%c%c %s", HB_UNTAG(tag), result ? "ok" : "FAILED");
   154    return result;
   155  }
