   157  static bool
   158  _should_drop_table(hb_subset_plan_t *plan, hb_tag_t tag)
   159  {
   160    switch (tag) {
   161      case HB_TAG ('c', 'v', 'a', 'r'): /* hint table, fallthrough */
   162      case HB_TAG ('c', 'v', 't', ' '): /* hint table, fallthrough */
   163      case HB_TAG ('f', 'p', 'g', 'm'): /* hint table, fallthrough */
   164      case HB_TAG ('p', 'r', 'e', 'p'): /* hint table, fallthrough */
   165      case HB_TAG ('h', 'd', 'm', 'x'): /* hint table, fallthrough */
   166      case HB_TAG ('V', 'D', 'M', 'X'): /* hint table, fallthrough */
   167        return plan->drop_hints;
   168      // Drop Layout Tables if requested.
   169      case HB_TAG ('G', 'D', 'E', 'F'): /* temporary */
   170      case HB_TAG ('G', 'P', 'O', 'S'): /* temporary */
   171      case HB_TAG ('G', 'S', 'U', 'B'): /* temporary */
   172        return plan->drop_ot_layout;
   173      // Drop these tables below by default, list pulled
   174      // from fontTools:
   175      case HB_TAG ('B', 'A', 'S', 'E'):
   176      case HB_TAG ('J', 'S', 'T', 'F'):
   177      case HB_TAG ('D', 'S', 'I', 'G'):
   178      case HB_TAG ('E', 'B', 'D', 'T'):
   179      case HB_TAG ('E', 'B', 'L', 'C'):
   180      case HB_TAG ('E', 'B', 'S', 'C'):
   181      case HB_TAG ('S', 'V', 'G', ' '):
   182      case HB_TAG ('P', 'C', 'L', 'T'):
   183      case HB_TAG ('L', 'T', 'S', 'H'):
   184      // Graphite tables:
   185      case HB_TAG ('F', 'e', 'a', 't'):
   186      case HB_TAG ('G', 'l', 'a', 't'):
   187      case HB_TAG ('G', 'l', 'o', 'c'):
   188      case HB_TAG ('S', 'i', 'l', 'f'):
   189      case HB_TAG ('S', 'i', 'l', 'l'):
   190      // Colour
   191      case HB_TAG ('s', 'b', 'i', 'x'):
   192        return true;
   193      default:
   194        return false;
   195    }
   196  }
