   198  /**
   199   * hb_subset:
   200   * @source: font face data to be subset.
   201   * @profile: profile to use for the subsetting.
   202   * @input: input to use for the subsetting.
   203   *
   204   * Subsets a font according to provided profile and input.
   205   **/
   206  hb_face_t *
   207  hb_subset (hb_face_t *source,
   208             hb_subset_profile_t *profile,
   209             hb_subset_input_t *input)
   210  {
   211    if (unlikely (!profile || !input || !source)) return hb_face_get_empty();
   212
   213    hb_subset_plan_t *plan = hb_subset_plan_create (source, profile, input);
   214
   215    hb_tag_t table_tags[32];
   216    unsigned int offset = 0, count;
   217    bool success = true;
   218    do {
   219      count = ARRAY_LENGTH (table_tags);
   220      hb_face_get_table_tags (source, offset, &count, table_tags);
   221      for (unsigned int i = 0; i < count; i++)
   222      {
   223        hb_tag_t tag = table_tags[i];
   224        if (_should_drop_table(plan, tag))
   225        {
   226          DEBUG_MSG(SUBSET, nullptr, "drop %c%c%c%c", HB_UNTAG(tag));
   227          continue;
   228        }
   229        success = success && _subset_table (plan, tag);
   230      }
   231      offset += count;
   232    } while (count == ARRAY_LENGTH (table_tags));
   233
   234    hb_face_t *result = success ? hb_face_reference(plan->dest) : hb_face_get_empty();
   235    hb_subset_plan_destroy (plan);
